import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { RouteProp, useRoute, useNavigation } from '@react-navigation/native';
import { auth } from '../services/firebaseConfig';
import type { ListaRotasPrincipais } from '../types';
import { MaterialIcons } from '@expo/vector-icons';
import { confirmAction } from '../utils/confirmAction';

type RotaDetalhesEscala = RouteProp<ListaRotasPrincipais, 'DetalhesEscala'>;

const db = getFirestore();

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
  // Adicione outros UIDs aqui
];

// Mapeamento de emojis para cada campo
const iconesPorCampo: Record<string, string> = {
  data: '📅',
  responsavel: '🧑‍💼',
  violao: '🎸',
  teclado: '🎹',
  bateria: '🥁',
  guitarra: '🎸',
  contrabaixo: '🪕',
  vocal: '🎙️',
  backVocal1: '🎤',
  backVocal2: '🎤',
  backVocal3: '🎤',
  backVocal4: '🎤',
  som: '🔊',
  projecao: '🖥️',
  midia1: '📱',
  midia2: '📱',
  midia3: '🎥',
  midia4: '📸',
  criadoEm: '⏰',
};

const ordemCampos: string[] = [
  'data',
  'responsavel',
  'violao',
  'teclado',
  'bateria',
  'guitarra',
  'contrabaixo',
  'vocal',
  'backVocal1',
  'backVocal2',
  'backVocal3',
  'backVocal4',
  'som',
  'projecao',
  'midia1',
  'midia2',
  'midia3',
  'midia4',
  'criadoEm',
];

function formatarData(valor: any) {
  if (valor?.toDate) {
    return valor.toDate().toLocaleString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }
  if (typeof valor === 'string' && !isNaN(Date.parse(valor))) {
    return new Date(valor).toLocaleString('pt-BR');
  }
  return String(valor);
}

function labelComAcento(campo: string): string {
  switch (campo) {
    case 'data': return 'Data';
    case 'responsavel': return 'Responsável';
    case 'violao': return 'Violão';
    case 'teclado': return 'Teclado';
    case 'bateria': return 'Bateria';
    case 'guitarra': return 'Guitarra';
    case 'contrabaixo': return 'Contrabaixo';
    case 'vocal': return 'Vocal';
    case 'backVocal1': return 'Back Vocal 1';
    case 'backVocal2': return 'Back Vocal 2';
    case 'backVocal3': return 'Back Vocal 3';
    case 'backVocal4': return 'Back Vocal 4';
    case 'som': return 'Som';
    case 'projecao': return 'Projeção';
    case 'midia1': return 'Mídia 1';
    case 'midia2': return 'Mídia 2';
    case 'midia3': return 'Mídia 3';
    case 'midia4': return 'Mídia 4';
    case 'criadoEm': return 'Criado em';
    default: return campo.charAt(0).toUpperCase() + campo.slice(1);
  }
}

const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

export default function TelaDetalhesEscala(): JSX.Element {
  const route = useRoute<RotaDetalhesEscala>();
  const navigation = useNavigation();
  const id = route.params?.id;

  const [escala, setEscala] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [editando, setEditando] = useState(false);
  const [escalaEdit, setEscalaEdit] = useState<any>({});

  // Animação de alto relevo para os botões
  const animBtn1 = React.useRef(new Animated.Value(1)).current;
  const animBtn2 = React.useRef(new Animated.Value(1)).current;

  useEffect(() => {
    setUidAtual(auth.currentUser?.uid ?? null);

    if (!id) return;
    const carregarEscala = async () => {
      try {
        const docSnap = await getDoc(doc(db, 'escalas', id));
        if (docSnap.exists()) {
          setEscala(docSnap.data());
          setEscalaEdit(docSnap.data());
        } else {
          setEscala(null);
        }
      } catch (e) {
        setEscala(null);
      } finally {
        setLoading(false);
      }
    };
    carregarEscala();
  }, [id]);

  // Máscara automática para data dd/mm/aaaa
  const handleChange = (campo: string, valor: string) => {
    if (campo === 'data') {
      let cleaned = valor.replace(/\D/g, '');
      if (cleaned.length > 8) cleaned = cleaned.slice(0, 8);
      let formatted = cleaned;
      if (cleaned.length > 4) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2, 4)}/${cleaned.slice(4)}`;
      } else if (cleaned.length > 2) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2)}`;
      }
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: formatted }));
    } else {
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: valor }));
    }
  };

  const salvarAlteracoes = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    try {
      await updateDoc(doc(db, 'escalas', id), escalaEdit);
      setEscala({ ...escalaEdit });
      setEditando(false);
      Alert.alert('Sucesso', 'Escala atualizada com sucesso!');
      // incrementa contador remoto e local para sinalizar atualização
      const metaRef = doc(db, 'meta', 'escalas');
      try {
        await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
      } catch (err) {
        try {
          await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
        } catch (e2) {
          console.log('Erro ao incrementar contador remoto após editar escala', e2);
        }
      }
      try {
        const cur = await AsyncStorage.getItem('nova_escala');
        const num = cur ? parseInt(cur, 10) || 0 : 0;
        const novo = num + 1;
        await AsyncStorage.setItem('nova_escala', String(novo));
        await Notifications.setBadgeCountAsync(novo);
      } catch (e) {
        console.log('Erro ao setar contador/badge local depois de editar escala', e);
      }
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível salvar as alterações.');
    }
  };

  const confirmarExclusao = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    confirmAction({
      title: 'Excluir Escala',
      message: 'Tem certeza que deseja excluir esta escala?',
      onConfirm: async () => {
        try {
          await deleteDoc(doc(db, 'escalas', id));
          Alert.alert('Sucesso', 'Escala excluída com sucesso!');
          // @ts-ignore
          if (navigation && navigation.goBack) navigation.goBack();
        } catch (error) {
          Alert.alert('Erro', 'Não foi possível excluir a escala.');
        }
      },
    });
  };

  if (!id) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <Text>ID da escala não informado.</Text>
        </View>
      </View>
    );
  }

  if (loading) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#ff9800" />
        </View>
      </View>
    );
  }

  if (!escala) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <Text>Escala não encontrada.</Text>
        </View>
      </View>
    );
  }

  const camposOrdenados = [
    ...ordemCampos.filter((campo) => escala[campo] !== undefined),
    ...Object.keys(escala).filter((campo) => !ordemCampos.includes(campo)),
  ];

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  // Efeito de alto relevo nos botões
  const handlePressIn = (anim: Animated.Value) => {
    Animated.spring(anim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = (anim: Animated.Value) => {
    Animated.spring(anim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <View style={styles.bg}>
      {/* HEADER NEUMÓRFICO PERSONALIZADO */}
      <View style={styles.headerNeumorphic}>
        <View style={styles.headerRow}>
          {/* Botão Home à esquerda */}
          <TouchableOpacity
            style={styles.headerIconBtn}
            onPress={() => navigation.navigate('Inicio')}
            activeOpacity={0.7}
          >
            <Image
  source={{ uri: 'https://img.icons8.com/?size=100&id=bIwuxbfp2H2N&format=png&color=000000.png' }}
  style={styles.headerIcon}
/>
          </TouchableOpacity>

          {/* Título centralizado */}
          <View style={styles.headerCenterBox}>
            <Text style={styles.novaEscalaText}>Detalhes da Escala</Text>
          </View>

          {/* Botão Voltar à direita */}
          <TouchableOpacity
            style={styles.headerIconBtn}
            onPress={() => navigation.goBack()}
            activeOpacity={0.7}
          >
            <Image
  source={{ uri: 'https://img.icons8.com/?size=100&id=CFDbApIER33U&format=png&color=000000.png' }}
  style={styles.headerIcon}
/>
          </TouchableOpacity>
        </View>
      </View>
      {/* FIM HEADER */}

      <ScrollView contentContainerStyle={styles.container}>
        <NeumorphicContainer style={styles.card}>
          {camposOrdenados.map((campo) => (
            <NeumorphicContainer key={campo} style={styles.inputGroup}>
              <View style={styles.labelRow}>
                <Text style={styles.emoji}>{iconesPorCampo[campo] || ''}</Text>
                <Text style={styles.label}>{labelComAcento(campo)}</Text>
              </View>
              {editando && campo !== 'criadoEm' ? (
                <TextInput
                  style={styles.input}
                  value={escalaEdit[campo]}
                  onChangeText={text => handleChange(campo, text)}
                  placeholder={labelComAcento(campo)}
                  placeholderTextColor="#90caf9"
                  maxLength={campo === 'data' ? 10 : 60}
                  selectionColor="#ff9800"
                  keyboardType={campo === 'data' ? 'numeric' : 'default'}
                  textAlign="right"
                  underlineColorAndroid="transparent"
                />
              ) : (
                <View style={styles.valorBox}>
                  <Text style={styles.valor}>
                    {campo === 'criadoEm' || campo === 'criadoem'
                      ? formatarData(escala[campo])
                      : String(escala[campo])}
                  </Text>
                </View>
              )}
            </NeumorphicContainer>
          ))}

          {permitido && (
            <View style={styles.acoesAdminNeumorphic}>
              {!editando ? (
                <>
                  <Animated.View style={{ flex: 1, marginRight: 10, transform: [{ scale: animBtn1 }] }}>
                    <TouchableOpacity
                      style={styles.saveButton}
                      onPress={() => setEditando(true)}
                      onPressIn={() => handlePressIn(animBtn1)}
                      onPressOut={() => handlePressOut(animBtn1)}
                      activeOpacity={0.85}
                    >
                      <Text style={styles.saveButtonText}>Editar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                  <Animated.View style={{ flex: 1, transform: [{ scale: animBtn2 }] }}>
                    <TouchableOpacity
                      style={[styles.saveButton, { backgroundColor: '#F44336' }]}
                      onPress={confirmarExclusao}
                      onPressIn={() => handlePressIn(animBtn2)}
                      onPressOut={() => handlePressOut(animBtn2)}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.saveButtonText, { color: '#fff' }]}>Excluir</Text>
                    </TouchableOpacity>
                  </Animated.View>
                </>
              ) : (
                <>
                  <Animated.View style={{ flex: 1, marginRight: 10, transform: [{ scale: animBtn1 }] }}>
                    <TouchableOpacity
                      style={styles.saveButton}
                      onPress={salvarAlteracoes}
                      onPressIn={() => handlePressIn(animBtn1)}
                      onPressOut={() => handlePressOut(animBtn1)}
                      activeOpacity={0.85}
                    >
                      <Text style={styles.saveButtonText}>Salvar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                  <Animated.View style={{ flex: 1, transform: [{ scale: animBtn2 }] }}>
                    <TouchableOpacity
                      style={[styles.saveButton, { backgroundColor: '#b3e5fc' }]}
                      onPress={() => {
                        setEditando(false);
                        setEscalaEdit({ ...escala });
                      }}
                      onPressIn={() => handlePressIn(animBtn2)}
                      onPressOut={() => handlePressOut(animBtn2)}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.saveButtonText, { color: '#23243a' }]}>Cancelar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                </>
              )}
            </View>
          )}
        </NeumorphicContainer>
      </ScrollView>
    </View>
  );
}

